                    "【端正好】我本是个钓鱼人，却做了扶犁叟。叹英布、彭越、韩侯。敛我这一身外两只拿云手，再不出麻袍袖。",
                    "【滚绣球】我如今聚村叟，会诗友，飧的是活鱼新酒。问甚瓦盆砂钵磁瓯，推台不换盏，高歌自打手。任从他阴晴昏昼，我直吃的醉时眠衲被蒙头。睡彻窗外三竿日，为的傲杀人间万户侯，倒大优游。",
                    "【倘秀才】林泉下浊生爽口，御宴上堂食惹手。留的前生喝下酒。你道这一山汉，共那寿亭侯，是故友。",
                    "【滚绣球】你着我就席上央他几瓯。那汉劣性子输了半筹，问甚么安排来后。马孟起是杀人的领袖，那杀汉虎牢关立伏了十八路诸侯，骑一疋千里驹，横一条丈八矛。当阳坡有如雷吼，曾挡住曹丞相一百万带甲貔貅。叫一声，混天尘土纷纷的桥先断；喝一声，拍岸惊涛厌厌的水逆流。这一火怎肯干休。",
                    "【叨叨令】若是你冬冬战鼓声相凑，不剌剌战马望前骤；他恶喑喑掀起征袍袖，不邓邓恼犯难收。救你索与他死去也么哥，救你索与他死去也么哥，那一柄青龙刀落处都多透。",
                    "【煞尾】席你儿，怕刺着我手；树叶儿，提防打破我头。他千里独行觅二友，匹马单刀镇九州。人似巴山越岭彪，马跨翻江混海虬。他轻举龙泉杀车胄，怒拔昆吾坏文丑；麾盖下颜良剑枭了首，蔡阳英雄立取了头。这个避是非的先生决应了口。吾兄呵，那杀人的关公，更怕他下不得手。"
