                    "【粉蝶儿】天下荒荒，却周秦早属了刘项。楚君臣遥指咸阳，一个力拔山，一个量容海，这两个一时开创。想当日黄阁乌江，一个用了三杰，一个立诛了八将。",
                    "【醉春风】一个短剑一身亡，一个净鞭三下响。暗想祖宗传授与儿孙，却都是枉，枉，枉。献帝又无靠无挨，董卓又不仁不义，吕布又一冲一撞。",
                    "【十二月】那时节兄弟在范阳，兄长在楼桑，关某在解良，诸葛在南阳。一时英雄四方，结义了皇叔关张。",
                    "【尧民歌】一年三谒卧龙冈，早鼎足三分汉家邦。俺哥哥称孤道寡作蜀王，关某匹马单刀镇荆襄。长江，经今几战场，恰便似后浪催前浪。",
                    "【鲍老儿】战鼓才挝斩了蔡阳，血溅在沙场上。刀挑了征袍离了许昌，辞了曹丞相。向单刀会上，对两朝文武，更小可如三月襄阳。",
