                    "【仙吕·点绛唇】妓女追陪。觅钱一世。临收计。怎做的百纵千随。知重咱风流媚。",
                    "【混江龙】我想这姻缘匹配。少一时一刻强难为。如何可意。怎的相知。怕不便脚搭着脑杓成事早。怎知他手拍着胸脯悔后迟。寻前程。觅下稍。恰便是黑海也似难寻觅。料的来人心不问。天理难欺。",
                    "【油葫芦】姻缘簿全凭我共你。谁不待拣个称意的。他每都拣来拣去百千回。待嫁一个老实的又怕尽世儿难成对。待嫁一个聪俊的又怕半路里轻抛弃。遮莫向狗溺处藏。遮莫向牛屎里堆。忽地便吃了一个合扑地。那时节睁着眼怨他谁。",
