                    "【倘秀才】我当初倚大呵妆儇主婚。怎知我嫉妒呵特故里破亲。你这厮外相儿通疏就里村。你今日结婚姻。咱就肯罢论。",
                    "【脱布衫】我更是的不待饶人。我为甚不敢明闻。肋底下插此木自稳。怎见你便打他一顿。",
