                  "note": "底本：明《元曲选》本，参照中国古典戏曲资料库《元曲选·救风尘·第三折》。本折是全剧最重要的行动段落：赵盼儿乔装赴郑州，以假意求嫁诱使周舍答应休弃宋引章，最终取得休书。\n第三折采用“乔装—试探—激将—假意求嫁—取得休书”的连续行动结构。赵盼儿并非靠武力取胜，而是准确识别周舍的好色、虚荣和贪财心理，以其熟悉的风月语言反过来控制他。她的策略同时具有喜剧性、危险性和现实性，是《救风尘》最具代表性的戏剧设计。",
