                    "【双调·新水令】笑吟吟案板似写着休书。则俺这脱空的故人何处。卖弄他能爱女。有权术。怎禁那得胜葫芦。说到有九千句。",
                    "【乔牌儿】酒和羊车上物。大红罗自将去。你一心淫滥无是处。要将人白赖取。",
                    "【庆东原】俺须是卖空虚。凭着说来的言呪誓为活路。怕你不信呵。遍花街请到娼家女。那一个不对着明香宝烛。那一个不指着皇天后土。那一个不赌着鬼戮神诛。若信这呪盟言。早死的绝门户。",
                    "【落梅风】则为你无思虑。忒糢糊。周舍云休书已毁了。你不跟我去待怎么。正旦云妹子休慌莫怕。咬碎的是假休书。我特故抄与你个休书题目。我跟前见放着这亲模。便有九头牛也拽不出去。",
