                    "【仙吕·点绛唇】满腹闲愁，数年禁受，天知否？天若是知我情由，怕不待和天瘦。",
                    "【混江龙】则问那黄昏白昼，两般儿忘餐废寝几时休？大都来昨宵梦里，和着这今日心头。催人泪的是锦烂熳花枝横绣闼，断人肠的是剔团圞月色挂妆楼。长则是急煎煎按不住意中焦，闷沉沉展不彻眉间皱。越觉的情怀冗冗，心绪悠悠。",
