                    "【天下乐】莫不是前世里烧香不到头，今也波生招祸尤，劝今人早将来世修。我将这婆侍养，我将这服孝守，我言词须应口。",
                    "【一半儿】为什么泪漫漫不住点儿流？莫不是为索债与人家惹争斗？我这里连忙迎接慌问候，他那里要说缘由。则见他一半儿徘徊一半儿丑。",
                    "【后庭花】避凶神要择好日头，拜家堂要将烟火修；梳着个霜雪般白䯼髻，怎将这云霞般锦帕兜？怪不的女大不中留。你如今六旬左右，可不道到中年万事休！旧恩爱一笔勾，新夫妻两意投，枉教人笑破口。",
                    "【青哥儿】你虽然是得他得他营救，须不是笋条笋条年幼，刬的便巧画蛾眉成配偶。想当初你夫主遗留，替你图谋，置下田畴，早晚羹粥，寒暑衣裘，满望你鳏寡孤独，无捱无靠，母子每到白头。公公也，则落得干生受。",
                    "【寄生草】你道他匆匆喜，我替你倒细细愁：愁则愁兴阑删咽不下交欢酒，愁则愁眼昏腾扭不上同心扣，愁则愁意朦胧睡不稳芙蓉褥。你待要笙歌引至画堂前，我道这姻缘敢落在他人后。",
