                    "【南吕·一枝花】他则待一生鸳帐眠，那里肯半夜空房睡；他本是张郎妇，又做了李郎妻。有一等妇女每相随，并不说家克计，则打听些闲是非；说一会不明白打凤的机关，使了些调虚嚣捞龙的见识。",
                    "【梁州第七】这一个似卓氏般当垆涤器，这一个似孟光般举案齐眉，说的来藏头盖脚多伶俐！道着难晓，做出才知。旧恩忘却，新爱偏宜；坟头上土脉犹湿，架儿上又换新衣。那里有奔丧处哭倒长城？那里有浣纱时甘投大水？那里有上山来便化顽石？可悲，可耻！妇人家直恁的无仁义。多淫奔，少志气，亏杀前人在那里，更休说百步相随。",
                    "【南吕·隔尾】（第一次）你说道少盐欠醋无滋味，加料添椒才脆美。但愿娘亲早痊济，饮羹汤一杯，胜甘露灌体，得一个身子平安倒大来喜。",
                    "【南吕·贺新郎】一个道你请吃，一个道婆先吃，这言语听也难听，我可是气也不气！想他家与咱家有甚的亲和戚？怎不记旧日夫妻情意，也曾有百纵千随？婆婆也，你莫不为“黄金浮世宝，白发故人稀”，因此上把旧恩情，全不比新知契？则待要百年同墓穴，那里肯千里送寒衣？",
                    "【南吕·斗虾蟆】空悲戚，没理会，人生死，是轮回。感着这般病疾，值着这般时势，可是风寒暑湿，或是饥饱劳役，各人症候自知。人命关天关地，别人怎生替得？寿数非干今世。相守三朝五夕，说甚一家一计？又无羊酒缎匹，又无花红财礼；把手为活过日，撒手如同休弃。不是窦娥忤逆，生怕旁人论议。不如听咱劝你，认个自家晦气，割舍的一具棺材停置，几件布帛收拾，出了咱家门里，送入他家坟地。这不是你那从小儿年纪指脚的夫妻。我其实不关亲，无半点恓惶泪。休得要心如醉，意似痴，便这等嗟嗟怨怨，哭哭啼啼。",
                    "【南吕·隔尾】（第二次）这厮搬调咱老母收留你，自药死亲爷待要唬吓谁？我一马难将两鞍鞴，想男儿在日曾两年匹配，却教我改嫁别人，其实做不得。",
                    "【南吕·牧羊关】大人你明如镜，清似水，照妾身肝胆虚实。那羹本五味俱全，除了外百事不知。他推道尝滋味，吃下去便昏迷。不是妾讼庭上胡支对，大人也，却教我平白地说甚的？",
                    "【南吕·骂玉郎】这无情棍棒教我捱不的。婆婆也，须是你自做下，怨他谁？劝普天下前婚后嫁婆娘每，都看取我这般傍州例。",
