                    "【正宫·端正好】没来由犯王法，不提防遭刑宪，叫声屈动地惊天！顷刻间游魂先赴森罗殿，怎不将天地也生埋怨？",
                    "【正宫·滚绣球】有日月朝暮悬，有鬼神掌著生死权，天地也，只合把清浊分辨，可怎生糊突了盗跖、颜渊？为善的受贫穷更命短，造恶的享富贵又寿延。天地也，做得个怕硬欺软，却元来也这般顺水推船。地也，你不分好歹何为地？天也，你错勘贤愚枉做天！哎，只落得两泪涟涟。",
                    "【正宫·倘秀才】则被这枷扭的我左侧右偏，人拥的我前合后偃，我窦娥向哥哥行有句言。前街里去心怀恨，后街里去死无冤，休推辞路远。",
                    "【正宫·叨叨令】可怜我孤身只影无亲眷，则落的吞声忍气空嗟怨。早已是十年多不睹爹爹面。枉将他气杀也么哥，枉将他气杀也么哥！告哥哥，临危好与人行方便。",
                    "【正宫·快活三】念窦娥葫芦提当罪愆，念窦娥身首不完全，念窦娥从前已往干家缘。婆婆也，你只看窦娥少爷无娘面。",
                    "【正宫·鲍老儿】念窦娥伏侍婆婆这几年，遇时节将碗凉浆奠；你去那受刑法尸骸上烈些纸钱，只当把你亡化的孩儿荐。婆婆也，再也不要啼啼哭哭，烦烦恼恼，怨气冲天。这都是我做窦娥的没时没运，不明不暗，负屈衔冤。",
                    "【正宫·耍孩儿】不是我窦娥罚下这等无头愿，委实的冤情不浅；若没些儿灵圣与世人传，也不见得湛湛青天。我不要半星热血红尘洒，都只在八尺旗枪素练悬。等他四下里皆瞧见，这就是咱苌弘化碧，望帝啼鹃。",
