                    "【正宫·一煞】你道是天公不可期，人心不可怜，不知皇天也肯从人愿。做甚么三年不见甘霖降？也只为东海曾经孝妇冤，如今轮到你山阳县。这都是官吏每无心正法，使百姓有口难言！",
