                    "【双调·沉醉东风】我是那提刑的女孩，须不比现世的妖怪。怎不容我到灯影前，却拦截在门木呈外？我那爷爷呵，枉自有势剑金牌，把俺这屈死三年的腐骨骸，怎脱离无边苦海？",
                    "【双调·乔牌儿】则见他疑心儿胡乱猜，听了我这哭声儿转惊骇。哎，你个窦天章直恁的威风大，且受你孩儿窦娥这一拜。",
                    "【双调·雁儿落】你看这文卷曾道来不道来，则我这冤枉要忍耐如何耐？我不肯顺他人，倒着我赴法场；我不肯辱祖上，倒把我残生坏。",
                    "【双调·得胜令】呀，今日个搭伏定摄魂台，一灵儿怨哀哀。父亲也，你现拿着刑名事，亲蒙圣主差。端详这文册，那厮乱纲常，合当败。便万剐了乔才，还道报冤仇不畅怀！",
                    "【双调·川拨掉】猛见了你这吃敲材，我只问你这毒药从何处来？你本意待暗里栽排，要逼勒我和谐，倒把你亲爷毒害，怎教咱替你耽罪责！",
                    "【双调·七弟兄】你只为赖财，放乖，要当灾。〔带云〕这毒药呵，原来是你赛卢医出卖，张驴儿买，没来由填做我犯由牌，到今日官去衙门在。",
                    "【双调·梅花酒】你道是咱不该，这招状供写的明白。本一点孝顺的心怀，倒做了惹祸的胚胎。我只道官吏每还覆勘，怎将咱屈斩首在长街！第一要素旗枪鲜血洒，第二要三尺雪将死尸埋，第三要三年旱示天灾：咱誓愿委实大。",
                    "【双调·收江南】呀，这的是衙门从古向南开，就中无个不冤哉。痛杀我娇姿弱体闭泉台，早三年以外，则落的悠悠流恨似长淮。",
                    "【双调·鸳鸯煞尾】从今后把金牌势剑从头摆，将滥官污吏都杀坏，与天子分忧，万民除害。嘱付你爹爹，收养我奶奶。要怜他无妇无儿，谁管顾年衰迈！再将那文卷舒开，爹爹，也把我窦娥名下，屈死的招伏罪名儿改。本节完成：《窦娥冤》楔子、四折的曲牌系统已经全部建立；其中第一、二、三、四折均已分别整理曲牌、曲词和注解。杂剧作品仍作为“曲牌系统单位”管理，不重复计入散曲独立篇数。"
