                  "title": "汉宫秋·第四折",
                  "form": "杂剧 · 全折曲词",
                  "original": [
                    "【中吕·粉蝶儿】宝殿凉生，夜迢迢六宫人静。对银台一点寒灯，枕席间、临寝处，越显的吾身薄幸。万里龙廷，知他宿谁家一灵真性。",
                    "【中吕·醉春风】烧尽御炉香，再添黄串饼。想娘娘似竹林寺不见半分形，则留下这个影、影。未死之时，再生之日，我可也一般恭敬。",
                    "【中吕·叫声】高唐梦苦难成，那里也爱卿、爱卿，却怎生无些灵圣？偏不许楚襄王枕上雨云情。",
                    "【中吕·剔银灯】恰才这搭儿单于王使命，呼唤俺那昭君名姓。偏寡人唤娘娘不肯灯前应，却原来是画上的丹青。猛听得仙音院凤管鸣，更说甚箫韶九成。",
                    "【中吕·蔓青菜】白日里无承应，教寡人不曾一觉到天明，做的个团圆梦境。却原来雁叫长门两三声，怎知道更有个人孤另。",
                    "【中吕·白鹤子】多管是春秋高，筋力短，莫不是食水少，骨毛轻？待去后，愁江南网罗宽；待向前，怕塞北雕弓硬。",
                    "【中吕·幺篇】伤感似替昭君思汉主，哀怨似作薤露哭田横，凄怆似和半夜梦歌声，悲切似唱三叠阳关令。",
                    "【中吕·上小楼】早是我神思不安，又添个冤家缠定。他叫得慢一会儿紧一声儿，和尽寒更。不争你打盘旋，这搭里同声相应，可不差讹了四时节令？",
                    "【中吕·幺篇】你却待寻子卿、觅李陵，对着银台，叫醒咱家，对影生情。则俺那远乡的汉明妃虽然得命，不见你个泼毛团也耳根清净。",
                    "【中吕·满庭芳】又不是心中爱听，大古似林风瑟瑟，岩溜冷冷。我只见山长水远天如镜，又生怕误了你途程。见被你冷落了潇湘暮景，更打动我边塞离情，还说甚雁过留声。那堪更瑶阶夜永，嫌杀月儿明。",
                    "【中吕·十二月】休道是咱家动情，你宰相每也生憎。不比那雕梁燕语，不比那锦树莺鸣。汉昭君离乡背井，知他在何处愁听！",
                    "【中吕·尧民歌】呀呀的飞过蓼花汀，孤雁儿不离了凤凰城。画檐间铁马响丁丁，宝殿中御榻冷清清。寒也波更，萧萧落叶声，烛暗长门静。"
                  ],
