                    "【天下乐】我可便提起东来忘了西。梅香云昨日几家来问亲。小姐不语怎麼。正旦唱咱萱堂又觑着面皮。至如个穷人家女孩儿到十六七。或是誰家来问亲。那家来做媒。你教女孩儿羞答答说甚的。",
                    "【那吒令】本待要送春向池塘草萋。我且来散心到荼蘼架底。我待教寄身在蓬莱洞里。蹙金莲红绣鞋。荡湘裙鸣环珮。转过那曲槛之西。",
                    "【鹊踏枝】怎肯道负花期。惜芳菲。粉悴胭憔。他绿暗红稀。九十日春光如过隙。怕春归又早春归。",
                    "【寄生草】柳暗青烟密。花残红雨飞。这人人和柳浑相类。花心吹得人心碎。柳眉不转蛾眉繫。为甚西园陡恁景狼籍。正是东君不管人憔悴。",
                    "【么篇】榆散青钱乱。梅攒翠豆肥。轻轻风趁蝴蝶队。霏霏雨过蜻蜓戏。融融沙暖鸳鸯睡。落红踏践马蹄尘。残花酝酿蜂儿蜜。",
                    "【金盏儿】兀那画桥西。猛听的玉骢嘶。便好道杏花一色红千里。和花掩映美容仪。他把乌靴挑宝镫。玉带束腰围。真乃是能骑高价马。会着及时衣。",
                    "【后庭花】休道是转星眸上下窥。恨不的倚香腮左右偎。便锦被翻红浪。罗裙作地席。既待要暗偷期。咱先有意。爱别人可舍了自己。",
                    "【么篇】你道是情词寄与谁。我道来新诗权作媒。我映丽日墙头望。他怎肯袖春风马上归。怕的是外人知。你便叫天叫地。哎。小梅香好不做美。",
                    "【赚煞】这一堵粉墙儿低。这一带花阴儿密。与你个在客的刘郎说知。虽无那流出胡麻香饭水。比天台山到径抄直。莫疑迟。等的那斗转星移。休教这印苍苔的凌波袜儿湿。将湖山困倚。把角门儿虚闭。这后花园权做武陵溪。"
