                  "note": "第二折前五曲由等待、祈月、安排路线到谨慎潜行，完整表现夜间赴约的行动过程。李千金不是单纯等待裴少俊到来，而是和梅香共同策划、评估危险和布置空间。深宅大院既是家庭保护空间，也是礼法监视空间。\n第二折中段从角门、夜香和报时声开始，经过闺房亲密、嬷嬷发现，转入李千金替裴少俊辩护。李千金的策略包括：说明官差身份、引用爱情典故、承认双方情意、拒绝接受“奸盗”定义。作品由私情场景转向社会命名和伦理争论。\n第二折从月下赴约进入闺房亲密，继而被嬷嬷发现。冲突没有立即通过父母或官府解决，而是由李千金辩护、嬷嬷权衡风险，最后形成“先出走、待得官再认亲”的临时方案。爱情、女性行动、家庭名声和男性功名在此共同构成戏剧机制。",
