                    "【沽美酒】本是好人家女艳冶。便待要兴词讼发文牒。送到官司遭痛决。人心非铁。逢赦不该赦。",
                    "【太平令】随汉走怎说三贞九烈。勘奸情八棒十挟。谁识他歌台舞榭。甚的是茶房酒舍。相公便把贱妾。拷折下截。并不是风尘烟月。",
                    "【川拨棹】赛灵辄。蒯文通。李左车。都不似季布喉舌。王伯当尸叠。更做道向人处无过背说。是和非须辨别。",
                    "【七弟兄】是那些劣忄敞。痛伤嗟也。时乖运蹇遭磨灭。冰清玉洁肯随邪。怎生的拆开我连理同心结！",
                    "【梅花酒】他毒肠狠切。丈夫又软揣些些。相公又恶噷噷乖劣。夫人又叫丫丫似蝎蜇。你不去望夫石上变化身。筑坟台上立个碑碣。待教我谩忄敞忄敞。愁万缕。闷千叠。心似醉。意如焦。眼似瞎。手如瘸。轻拈掇。慢拿捻。",
                    "【收江南】呀！王吉叮珰掂做了两三截。有鸾胶难续玉簪折。则他这夫妻儿女两离别。总是我业彻。也强如参辰日月不交接。",
