                    "【沉醉东风】梦惊破情缘万结。路迢遥烟水千叠。常言道有亲娘有后爷。无亲娘无疼热。他要送我到官司。逞尽豪杰。多谢你把一双幼女痴儿好觑者。我待信拖拖去也。",
