                    "【折桂令】果然人生最苦是离别。方信道花发风筛。月满云遮。谁更敢倒凤颠鸾。撩蜂剔蝎。打草惊蛇。坏了咱墙头上传情简帖。拆开咱柳阴中莺燕蜂蝶。儿也咨嗟。女又拦截。既瓶坠簪折。咱义断恩绝！",
