                  "note": "第三折前段先交代七年幽居和一双儿女，再通过清明祭祖、孩子游园和裴尚书偶然进入后花园，使隐秘家庭被迫进入公开视野。李千金对父母的思念、对裴少俊功名的期待和对孩子安全的照料，共同构成她在第三折中的复杂身份。\n第三折中段把后花园家庭秘密转化为公开审判：裴尚书先怀疑李千金出身，再以官府刑罚相威胁；李千金则以官宦家庭身份、清白品行和夫妻关系反驳。院公的辩护和裴尚书的误认，共同显示身份信息如何决定人物在家庭和社会中的待遇。\n第三折后段以玉簪、银瓶、冰弦等器物把婚姻关系物质化、程序化。裴尚书以“天赐姻缘”之名设置试验，实际上由家长权力裁定婚姻；李千金一方面承认传统妇德，另一方面坚持自己并无淫邪过失。最终休书使夫妻、母子同时分离，第三折的冲突达到高潮。\n第三折以母子诀别收束。李千金被逐，但她并没有被写成没有历史的“残花败柳”：她有七年共同生活，有一双子女，有对家庭的照料，有对自身清白的辩护，也有对裴少俊的责问。第三折把第一、二折的爱情行动转化为婚姻制度冲突，第四折的重新认亲和团圆正是在这一断裂之后展开。",
