                        "羽衣：本指羽毛制成的衣服，也可泛指轻薄华美的衣裳；此处突出衣料随风而动。",
                        "丁东：形容玉佩、环佩相碰的声音。",
                        "银河：天河，七夕牛郎织女故事的重要天象。",
                        "玉蓬瀛：仙山、仙境的代称，写人物仿佛置身神仙世界。"
