                        "银汉鹊桥：银河和由喜鹊搭成的桥，指牛郎织女一年一度的相会。",
                        "不甫能：好不容易、才刚刚。元曲常用口语表达时间和情绪的急促转换。",
                        "晓鸡鸣：报晓的鸡鸣，意味着夜尽、相会结束。",
                        "情脉脉：情意深长而含蓄，也含有难以排遣的离愁。",
                        "泠泠：清冷、滴落声或泪水不断的状态；具体语感须结合句中“别泪”理解。"
