                    "【越调·紫花儿序】等待那齐齐整整，袅袅婷婷，姐姐莺莺。一更之后，万籁无声，直至莺庭。若是回廊下没揣的见俺可憎，将他来紧紧的搂定；只问你那会少离多，有影无形。",
                    "【越调·金蕉叶】猛听得角门儿呀的一声，风过处衣香细生。踮着脚尖儿仔细定睛，比我那初见时庞儿越整。",
                    "【越调·调笑令】我这里甫能、见娉婷，比着那月殿嫦娥也不恁般撑。遮遮掩掩穿芳径，料应来小脚儿难行。可喜娘的脸儿百媚生，兀的不引了人魂灵！",
                    "【越调·小桃红】夜深香霭散空庭，帘幕东风静。拜罢也斜将曲栏凭，长吁了两三声。剔团圞明月如悬镜。又不见轻云薄雾，都只是香烟人气，两般儿氤氲得不分明。",
                    "【越调·秃厮儿】早是那脸儿上扑堆着可憎，那堪那心儿里埋没着聪明。他把那新诗和得忒应声，一字字，诉衷情，堪听。",
                    "【越调·圣药王】那语句清，音律轻，小名儿不枉了唤做莺莺。他若是共小生、厮觑定，隔墙儿酬和到天明。方信道“惺惺的自古惜惺惺。”",
                    "【越调·麻郎儿】我拽起罗衫欲行，他陪着笑脸儿相迎。",
                    "【越调·幺篇】我忽听、一声、猛惊。原来是扑刺刺宿鸟飞腾，颤巍巍花梢弄影，乱纷纷落红满径。",
                    "【越调·络丝娘】空撇下碧澄澄苍苔露，明皎皎花筛月影。白日凄凉枉耽病，今夜把相思再整。",
                    "【越调·东原乐】帘垂下，户已扃，却才个悄悄相问，他那里低低应，月朗风清恰二更，厮觑幸：他无缘，小生薄命。",
                    "【越调·绵搭絮】恰寻归路，伫立空庭，竹梢风摆，斗柄云横。呀！今夜凄凉有四星，他不瞅人待怎生！虽然是眼角儿传情，咱两个口不言心自省。",
                    "【越调·拙鲁速】对着盏碧荧荧短檠灯，倚着扇泠清清旧帏屏。灯儿又不明，梦儿又不成；窗儿外淅零零的风儿透疏檑，忒楞楞的纸条儿鸣；枕头儿上孤另，被窝儿里寂静。你便是铁石人，铁石人也动情。",
                    "【越调·幺篇】怨不能，恨不成，坐不安，睡不宁。有一日柳遮花映，雾帐云屏，夜阑人静，海誓山盟。恁时节风流嘉庆，锦片也似前程，美满恩情，咱两个画堂自生。"
