                    "风约湘裙翠：风吹动女子翠色裙裾；“湘裙”是对女子衣裙的美称。",
                    "一曲琵琶数行泪：弹奏一曲琵琶便流下数行泪，写音乐触发相思。",
                    "芙蓉开尽：荷花全部开放又将谢尽，暗示等待时间很长。",
                    "红鸳白鹭：水鸟成双或成群，与人物独处形成反衬。",
