                    "折柄难擎露：荷柄折断，已不能托住露珠。",
                    "藕丝无：藕丝断绝，既写荷叶衰败，也带有情断意象。",
                    "倩风扶：请风来扶持，拟人化写枯荷。",
                    "不乘珠：不能承托露珠。",
                    "滩头鹭：滩边白鹭，反衬枯荷的孤寂。"
