                    "老瓦盆：民间常用的粗朴酒器。",
                    "翁媪：老年夫妇。",
                    "髻双鸦：梳成双丫髻，形状如乌鸦双翅，写农村女孩的发式。",
                    "转眄移时：转眼注视了很久。",
