                  "title": "一枝花·咏喜雨",
                  "form": "散曲 · 套数 · 南吕",
                  "original": [
                    "〔一枝花〕用尽我为国为民心，祈下些值金值玉雨。数年空盼望，一旦遂沾濡，唤省焦枯。喜万象春如故，恨流民尚在途，留不住都弃业抛家，当不的也离乡背土。",
                    "〔梁州〕恨不得把野草翻腾做菽粟，澄河沙都变化做金珠。直使千门万户家豪富，我也不枉了受天禄。眼觑着灾伤教我没是处，只落得雪满头颅。",
                    "〔尾声〕青天多谢相扶助，赤子从今罢叹吁。只愿得三日霖霪不停住，便下当街上似五湖，都渰了九衢，犹自洗不尽从前受过的苦。"
                  ],
                  "gloss": [
                    "沾濡：沾润、受雨水滋润",
                    "唤省：唤醒",
                    "流民：因灾荒等离开家园、流离失所的百姓",
                    "菽粟：豆类和谷物，泛指粮食",
                    "天禄：朝廷给予的俸禄",
                    "霖霪：久雨",
                    "赤子：百姓",
                    "渰：淹没",
                    "九衢：四通八达的道路，泛指城市街道。"
                  ],
                  "note": "南吕宫套曲，由〔一枝花〕、〔梁州〕、〔尾声〕三支曲牌组成。\n据古文岛所载，作品作于元文宗天历二年（1329）。张养浩奉召任陕西行台中丞，当时关中连年大旱，灾民困苦；他赴任途中曾祷雨于华山，到任后昼夜赈济灾民。雨至之后，作者写下此套曲，既有久旱逢雨的喜悦，也有对流民未归、灾情未尽的忧虑。\n首曲写祈雨成功和万物复苏，同时转出流民仍在逃难的“恨”；〔梁州〕以夸张愿望写作者希望野草化粮、河沙化金，使百姓家家富足，并以“受天禄”反省为官责任；〔尾声〕感谢天雨、祈愿继续降雨，即使街道积水如湖，也不足以洗尽百姓此前遭受的苦难。\n说明：常见异文包括“值金值玉／值金值玉雨”“唤省／唤醒”“霖霪／霖淫”“都渰了九衢／都淹了九衢”等。本文以古文岛正文为主，保留“值金值玉雨”“唤省”“霖霪”“渰”等通行古籍字样。",
