                    "迤逗：拖延、牵缠、反复纠结。",
                    "几遍成几遍休：关系反复聚合又离散。",
                    "惭羞：因情事、关系或自身处境而产生的羞惭。",
                    "三秋、三春：泛指长久的秋日和春日，不必拘泥于精确季节数目。",
