                    "横槊曹公：曹操横槊临江，写其英雄气概；“曹公”是对曹操的称呼。",
                    "紫盖黄旗：古代以紫盖、黄旗等祥瑞云气象征帝王之气，这里指孙吴有建立政权的天命意味。",
