                  "note": "作品的具体创作年份无可靠考证。它采用咏史方式，把曹操、孙权和诸葛亮分别置于赤壁及三国鼎立的历史节点中，重点在“英雄”评价，而非完整叙事。结尾“鼎足三分”把人物事功收束为政治格局，形成开阔、雄健的历史视野。文本中“多应借得”带有作者的推断语气，整理时不宜改写成“孙权完全凭天命取胜”等确定判断。",
