                  "note": "具体写作时间和对象无可靠考证。作品由楚地秋风起兴，经过故国山河、江南烟雨和孤鸿，转入邯郸道上的历史功业追问，最后以“何日论文”写对友朋或知音的期待。末三句的空间转换，使个人秋愁与时代、行旅和交游之思交织在一起。",
