                  "note": "具体创作年份不可考。作品从匆匆整理行装写起，经由关山、鹧鸪、阳关和旅舍，逐步加深离愁；中段借马周故事写怀才不遇，结尾以濛濛云树和东流春水把“愁浓”形象化。曲中典故丰富，但不能据此确定作者本人曾在新丰旅舍经历同样事件。",
