                    "山芋、山薯、山葱、山韭：山居中可以取得的食物，写生活简朴而自给。",
                    "山溜：山间流下的泉水或小溪。",
                    "冰敲月牙：以清脆声响和月牙形象写泉声的清越，是通感性比喻。",
                    "山色元佳：“元”通“原”，本来、原本之意。"
