                  "title": "蟾宫曲·怀古",
                  "form": "散曲 · 小令 · 双调",
                  "original": [
                    "问从来谁是英雄？",
                    "一个农夫，一个渔翁。",
                    "晦迹南阳，栖身东海，一举成功。",
                    "八阵图名成卧龙，六韬书功在飞熊。",
                    "霸业成空，遗恨无穷。",
                    "蜀道寒云，渭水秋风。"
                  ],
                  "gloss": [
                    "农夫：指姜尚，传说中曾在渭水边垂钓，后辅佐周文王、武王。",
                    "渔翁：指诸葛亮；“卧龙”故事中包含其未出仕时隐居、待时而动的形象。",
                    "晦迹南阳：诸葛亮隐居南阳，隐藏才迹以待时机。",
                    "栖身东海：姜尚相关传说中的隐居、垂钓意象；具体地点和传说版本有差异。",
                    "八阵图、卧龙：分别指诸葛亮的军事才略和“卧龙”称誉。",
                    "六韬、飞熊：《六韬》是传统上归于姜尚的兵书名；“飞熊”是姜尚受周文王礼聘前后的典故称谓。",
                    "霸业成空：功业终究归于消散，并非否定人物曾有的历史功绩。",
                    "蜀道寒云、渭水秋风：分别关联诸葛亮和姜尚，结尾由人物功业转为冷落苍凉的景象。"
                  ],
                  "note": "具体年代和写作事件不可考。作品用问答式开篇，把姜尚和诸葛亮并置为“农夫”“渔翁”，强调英雄并不必然出身显贵；中段以《六韬》、八阵图概括两人的功业，结尾却以“霸业成空、遗恨无穷”转入历史感慨，形成“成功—成空”的反转。",
